import logging

from pysnmp.hlapi.asyncio import Integer

from taf.hw.optical_switch.devices.base import OpticalSwitch
from taf.hw.optical_switch.devices.clients.snmp_client import SNMPClient
from taf.hw.optical_switch.exceptions import InvalidInput

# SNMP OIDs for Agiltron optical switch
#      1.3.6.1.4.1.40989.10.16.XX.4301.YY.0 where:
#      - XX is the slot number
#      - YY <1,7> basic card information's
#      - YY <8,19> card monitor information's
#     e.g. for
#         channel 1:
#             8 - max number of routes, read only (2 means two possible routes)
#             9 - current route, read/write (1 means route 1 is active)
#         channel 2:
#             10 - max number of routes, read only (2 means two possible routes)
#             11 - current route, read/write (1 means route 1 is active)
#         channel 6 (max number channels):
#             18 - max number of routes, read only (2 means two possible routes)
#             19 - current route, read/write (1 means route 1 is active)


class Agiltron(OpticalSwitch):
    """
    | Base class for Agiltron optical switches
    | Kwargs available in the interface:

    :param str host: IP address or domain name of the Agiltron device.
    :param int, optional timeout: Response timeout in seconds *(defaults to 10)*
    :param str, optional community_read: Community string used by SNMPv1/2 *(defaults to 'public')*
    :param str, optional community_write: Community string used by SNMPv1/2 *(defaults to 'private)*
    :param str, optional slot: Slot number of the Agiltron device *(defaults to '4')*
    """

    MAX_CHANNEL_NUMBER = 6  #: Maximum number of channels
    MAX_ROUTES = 2  #: Maximum number of routes

    def __init__(
        self,
        host,
        timeout=10,
        community_read="public",
        community_write="private",
        slot="4",
    ):
        """
        :param string host: IP address or domain name of the Agiltron device.
        :param int timeout: Response timeout in seconds.
        :param str community_read: Community string used by SNMPv1/2.
        :param str community_write: Community string used by SNMPv1/2.
        :param slot: Slot number of the Agiltron device.
        """
        self._snmp_client = SNMPClient(
            host=host,
            timeout=timeout,
            community_read=community_read,
            community_write=community_write,
        )

        self._key = f"1.3.6.1.4.1.40989.10.16.{slot}.4301"
        super().__init__(host, timeout)

    def set_optical_switch_channels(self, new_settings):
        """
        Set optical switch channels settings

        :param dict new_settings: dictionary with input channel as key and route as value.
            For example: ``{1:1, 2:1, 3:2, 4:1}``
        :raises InvalidInput(OpticalSwitchError): when input ``new_settings`` is incorrect. Channel is bigger than
            ``MAX_CHANNEL_NUMBER`` or route is not in range <1, ``MAX_ROUTES``>
        :raises OpticalSwitchConnectionError: when connection error occurred
        """
        for channel, value in new_settings.items():
            self._check_channel_assign_value_feasibility(int(channel), int(value))
            self._set_channel_value(int(channel), int(value))

    def get_optical_switch_channels(self):
        """
        Get information about optical switch channels

        :return: dictionary with input channel as key and output channel as value
        :raises OpticalSwitchConnectionError: when connection error occurred
        """
        statuses = {}

        for channel in range(1, self.MAX_CHANNEL_NUMBER + 1):
            channel_route = int(self._get_channel_value(channel))
            if channel_route == 0:
                break
            statuses[channel] = channel_route
        return statuses

    def _get_channel_value(self, channel):
        logging.info(f"SNMP: Fetching status for channel: {channel}")
        snmp_oid = self._build_snmp_oid(channel)
        oid_value = self._snmp_client.execute_get_cmd(snmp_oid)
        return oid_value

    def _set_channel_value(self, channel, value):
        logging.info(f"SNMP: Setting value {value} to channel {channel}")
        snmp_oid = self._build_snmp_oid(channel)
        self._snmp_client.execute_set_cmd(snmp_oid, Integer(value))

    def teardown(self):
        logging.info("No teardown operations defined for this device")

    def _build_snmp_oid(self, channel):
        return f"{self._key}.{self._channel_to_idx(channel)}.0"

    def _check_channel_assign_value_feasibility(self, channel, value):
        if not (1 <= channel <= self.MAX_CHANNEL_NUMBER):
            raise InvalidInput(f"Channel must be between 1 and {self.MAX_CHANNEL_NUMBER}")

        allowed_routes = range(1, self.MAX_ROUTES + 1)
        if value not in allowed_routes:
            raise InvalidInput(
                f"""Value {value} cannot be assigned to channel {channel}.
                               Value must be in {list(allowed_routes)}"""
            )

    @staticmethod
    def _channel_to_idx(channel):
        """
        :param int channel: channel number (1-6)
        :return: OID idx for current route of given channel
        for more information see SNMP OIDs  description for Agiltron optical switch, idx YY
        """
        return channel * 2 + 7
